INSERT INTO `berita` (`id`, `judul`, `konten`, `gambar`, `penulis_id`, `created_at`, `kategori`) VALUES
(12, 'Peringatan Hari Santri Nasional', 'Madrasah kita akan mengadakan peringatan Hari Santri Nasional pada minggu depan dengan berbagai lomba islami dan pengajian akbar. Seluruh santri diwajibkan menggunakan atribut lengkap.', NULL, 3, '2025-12-30 20:19:39', 'Berita Madrasah'),
(13, 'Ekstrakurikuler Baru: Tahfidz Qur\'an', 'Mulai bulan depan, madrasah akan membuka kelas khusus tahfidz Qur\'an bagi santri yang berminat. Pendaftaran dapat dilakukan di kantor tata usaha setiap jam kerja.', NULL, 3, '2025-12-30 20:19:39', 'Berita Madrasah'),
(14, 'Pembangunan Gedung Baru Selesai', 'Alhamdulillah, pembangunan gedung laboratorium komputer baru telah selesai dan siap digunakan. Fasilitas ini diharapkan dapat menunjang pembelajaran teknologi bagi santri.', NULL, 3, '2025-12-30 20:19:39', 'Berita Madrasah'),
(15, 'Kunjungan Wisata Religi ke Wali Songo', 'Rencana kegiatan akhir semester ini adalah kunjungan ziarah ke makam para wali di Jawa Tengah dan Jawa Timur. Santri diharapkan segera melunasi biaya administrasi.', NULL, 3, '2025-12-30 20:19:39', 'Berita Madrasah'),
(16, 'Pengumuman Libur Semester Ganjil', 'Diberitahukan kepada seluruh santri bahwa libur semester ganjil akan dimulai dari tanggal 20 Desember hingga 2 Januari. Santri masuk kembali pada tanggal 3 Januari.', NULL, 3, '2025-12-30 20:19:39', 'Berita Madrasah'),
(18, '📚✨ Kegiatan Belajar di Madrasah', 'be;ajar', '20260107015644_Logo_Kewirausahaan_Bg_White.png', 1, '2026-01-06 18:56:44', 'Kegiatan');

